CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, avatar_url) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', ''), COALESCE(NEW.raw_user_meta_data->>'avatar_url', '')) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER on_customer_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
INSERT INTO public.profiles(id, display_name, avatar_url) SELECT id, COALESCE(raw_user_meta_data->>'full_name', ''), COALESCE(raw_user_meta_data->>'avatar_url', '') FROM auth.users ON CONFLICT DO NOTHING;
ALTER TABLE public.orders ADD COLUMN user_id uuid;
CREATE INDEX orders_user_id_idx ON public.orders(user_id);
GRANT SELECT ON public.orders, public.order_items TO authenticated;
CREATE POLICY "Customers read own orders" ON public.orders FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Customers read own order items" ON public.order_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.orders o WHERE o.id = order_id AND o.user_id = auth.uid()));
CREATE TABLE public.customer_coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, code text NOT NULL, description text NOT NULL DEFAULT '', expires_at timestamptz, used_at timestamptz);
GRANT SELECT ON public.customer_coupons TO authenticated;
GRANT ALL ON public.customer_coupons TO service_role;
ALTER TABLE public.customer_coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Customers read own coupons" ON public.customer_coupons FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.cancel_customer_order(order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE target public.orders; item public.order_items; BEGIN SELECT * INTO target FROM public.orders WHERE id = order_id FOR UPDATE; IF target.id IS NULL OR target.user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF; IF target.status <> 'pending' THEN RAISE EXCEPTION 'Only pending orders can be cancelled'; END IF; UPDATE public.orders SET status = 'cancelled' WHERE id = order_id; FOR item IN SELECT * FROM public.order_items WHERE order_items.order_id = target.id LOOP IF item.variation_id IS NOT NULL THEN UPDATE public.product_variations SET stock = stock + item.quantity WHERE id = item.variation_id; ELSE UPDATE public.products SET stock = stock + item.quantity WHERE id = item.product_id; END IF; END LOOP; END; $$;
REVOKE ALL ON FUNCTION public.cancel_customer_order(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cancel_customer_order(uuid) TO authenticated;
CREATE FUNCTION public.guard_cancelled_order() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF OLD.status = 'cancelled' AND NEW.status <> 'cancelled' THEN RAISE EXCEPTION 'Cancelled orders cannot be reopened'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_cancelled_order BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_cancelled_order();